<?php
namespace App\Services;
final class HardwareFingerprint { private const KEYS=['machine_id','product_uuid','system_serial','board_serial','primary_disk_serial']; public function make(array $hardware,int $version=1):string { $parts=[]; foreach(self::KEYS as $key){$value=strtolower(trim((string)($hardware[$key]??''))); if($value!=='')$parts[$key]=$value;} ksort($parts); if(count($parts)<2) throw new \InvalidArgumentException('At least two stable hardware identifiers are required.'); return hash('sha256',$version.'|'.json_encode($parts,JSON_UNESCAPED_SLASHES)); } public function componentHashes(array $hardware):array { $map=['machine_id'=>'machine_id_hash','product_uuid'=>'product_uuid_hash','board_serial'=>'board_serial_hash','system_serial'=>'system_serial_hash','primary_disk_serial'=>'disk_serial_hash']; $out=[]; foreach($map as $input=>$column){$out[$column]=isset($hardware[$input])?hash('sha256',strtolower(trim((string)$hardware[$input]))):null;} return $out; } }
